theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2, u_1} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} {x_1 : MeasurableSpace α} {x_2 : MeasurableSpace β} {x_3 : MeasurableSpace δ}
  [inst : MeasurableSpace γ] (ξ : Kernel α β) [inst_1 : IsSFiniteKernel ξ] (κ : Kernel (α × β) (γ × δ))
  [inst_2 : IsSFiniteKernel κ] (x : α) (s : Set (β × δ)) (hs : MeasurableSet s) :
  ∫⁻ (b : β), (κ (x, b)) {c | (b, c) ∈ (fun p => (p.1, p.2.2)) ⁻¹' s} ∂ξ x =
    ∫⁻ (b : β), (κ.snd (x, b)) {c | (b, c) ∈ s} ∂ξ x := sorry

