  [inst_2 : IsSFiniteKernel κ] (x : α) (s : Set (β × δ)) (hs : MeasurableSet s) (b : β) :
  (κ (x, b)) {c | (b, c.2) ∈ s} = (κ (x, b)) {p | p.2 ∈ {c | (b, c) ∈ s}} := sorry

